import CardArt1 from "./bento-05/card-art-1";
import CardArt2 from "./bento-05/card-art-2";
import CardArt3 from "./bento-05/card-art-3";
import CardArt4 from "./bento-05/card-art-4";
import CardGlow from "./bento-05/card-glow";
import Flat from "./bento-05/flat";
import Globe from "./bento-05/globe";
import Glow from "./bento-05/glow";
import LoadIn, { LoadInGroup } from "./bento-05/load-in";
import { GLYPH_16, GLYPH_16_AT, GLYPH_AI } from "./bento-05/glyphs";
import "./bento-05/bento-05.css";

// The cards are the Figma exports as-is: each SVG already paints its own glass
// fill and 16px gradient border, so a cell is just a clip + a covering SVG.
// Real shadows are four falloffs, not one: a tight contact line where the card
// meets the page, then progressively softer and more offset layers as the light
// wraps. A single big blur reads as a sticker.
const shadow = [
  "shadow-[0_1px_1px_rgba(0,0,0,0.10),0_4px_8px_-2px_rgba(0,0,0,0.10),0_14px_28px_-8px_rgba(0,0,0,0.14),0_36px_64px_-20px_rgba(0,0,0,0.20)]",
  "dark:shadow-[0_1px_1px_rgba(0,0,0,0.45),0_4px_8px_-2px_rgba(0,0,0,0.40),0_14px_28px_-8px_rgba(0,0,0,0.50),0_36px_64px_-20px_rgba(0,0,0,0.65)]",
].join(" ");

// 24px to match the Figma frame radius; the SVGs carry the same 24 on their own
// base rect, clip and border stroke, so the clip and the artwork agree.
//
// No content-visibility here. It was worth it when a card off screen was still
// running a ripple and a grain field; below lg none of that exists any more, and
// what is left — painting artwork that is not on screen — a browser skips on its
// own. What it did keep doing was hiding anything inside it from an
// IntersectionObserver, which is a blank card for the price of an optimisation
// that had nothing left to save.
const cell = `absolute inset-0 overflow-hidden rounded-3xl ${shadow}`;
const fill = {
  className: "absolute inset-0 h-full w-full",
  preserveAspectRatio: "xMidYMid slice",
} as const;

// The ambilight lives in glow.tsx — desktop-only, and its copy of the artwork is
// code-split so the phone never carries it.

// "16+"/"AI" repainted opaque over the export's glass, per the Figma frames:
// F7F7F7 -> DFDFDF -> C3C3C3 with a 2px #FAFAFA rim. The ramp runs to 1.25 of
// the glyph, not 1 — Figma's handle ends well below the baseline (y=210 on a
// 169-tall glyph), so the letters only ever reach the middle of it and bottom
// out at a light grey.
//
// The rim goes under the fill (paintOrder) because the AI path is a union of
// overlapping subpaths — the A's crossbar is a full rectangle buried in its
// legs — so a plain stroke outlines every internal seam and the letter comes
// apart. Painted first, the fill covers the seams and only the outer half of
// the stroke survives, so 4 draws a 2px rim.
//
// slice, like the card art, so it stays welded to the glyph the SVG underneath
// already drew once the card crops.
//
// One ramp for both glyphs. The AI card used to hold its ramp near-solid past
// the crossbar, to keep the A's counter from closing — but the copy block is
// ~45% of the card below sm and the glyph runs 25px into it, so the hold put
// the title on a near-white letter. Held or not the letters cross the copy;
// what makes the "16+" card read is that they are half gone by the time they
// get there. So the AI card gets the same ramp. The crossbar staying legible
// was the underlying export's problem anyway: its outside-stroke rimmed that
// internal seam, and it is the rim, not the fade, that drew a box in the
// counter. That rim is gone from card-art-2 now.
//
// That ramp is anchored to the glyph's own box, which is the right anchor from
// sm up and the wrong one below it: on the 3/2 mobile card the copy takes the
// bottom ~40% and the ramp is only half done by the time it gets there, so the
// letters run through the title at half strength — legible, but the title is
// sitting on them. Hence a second, card-relative fade below sm, finished before
// the copy starts. What is left under the text is the export's own glass glyph,
// which is what it is for.
function Glyph({
  d,
  id,
  transform,
}: {
  d: string;
  id: string;
  transform?: string;
}) {
  const [y1, y2] = [0.35, 0.95];
  return (
    <svg
      aria-hidden
      viewBox="0 0 672 313"
      preserveAspectRatio="xMidYMid slice"
      className="pointer-events-none absolute inset-0 h-full w-full max-sm:[mask-image:linear-gradient(to_bottom,#000_22%,transparent_58%)]"
    >
      <defs>
        <linearGradient id={id} x1={0} y1={0} x2={0} y2={1.25}>
          <stop offset="0%" stopColor="#F7F7F7" />
          <stop offset="50%" stopColor="#DFDFDF" />
          <stop offset="100%" stopColor="#C3C3C3" />
        </linearGradient>
        {/* The letters dissolve into the card's dark bottom rather than
            ending on an edge. A mask, not a darker fill, because the rim
            has to go with them — and bbox units, so the same ramp fits
            either glyph. The rect overhangs the box because the rim is
            painted outside it, and anything the rect misses is masked
            away: at 1x1 it shaves the rim off the top of every letter. */}
        <linearGradient
          id={`${id}-fade`}
          gradientUnits="userSpaceOnUse"
          x1={0}
          y1={y1}
          x2={0}
          y2={y2}
        >
          <stop offset="0%" stopColor="#fff" />
          <stop offset="100%" stopColor="#fff" stopOpacity={0} />
        </linearGradient>
        <mask id={`${id}-mask`} maskContentUnits="objectBoundingBox">
          <rect
            x={-0.2}
            y={-0.2}
            width={1.4}
            height={1.4}
            fill={`url(#${id}-fade)`}
          />
        </mask>
      </defs>
      <path
        d={d}
        transform={transform}
        fill={`url(#${id})`}
        stroke="#FAFAFA"
        strokeWidth={4}
        paintOrder="stroke"
        mask={`url(#${id}-mask)`}
      />
    </svg>
  );
}

// Copy sits on dark artwork in both themes, so it stays light; the scrim keeps
// it legible where the gradients bloom.
function CardCopy({
  title,
  sub,
  className = "",
}: {
  title: string;
  sub: string;
  className?: string;
}) {
  return (
    <div
      className={`absolute inset-x-0 z-10 flex flex-col gap-1.5 p-5 sm:p-6 lg:p-7 ${className}`}
    >
      <h3 className="text-balance text-base font-semibold tracking-tight text-white sm:text-lg">
        {title}
      </h3>
      <p className="max-w-[46ch] text-pretty text-xs leading-relaxed text-white/65 sm:text-sm">
        {sub}
      </p>
    </div>
  );
}

// The 48px pattern tile is just a 6px cell repeated 8×8: a diamond, a 1×3
// vertical dash and a 3×1 horizontal dash. Drawn as a mask (alpha only) so the
// ink follows the theme instead of shipping a light and a dark copy.
const patternUrl = `url("data:image/svg+xml,${encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="6" height="6" fill="#000"><path d="M5 1h1v3H5z"/><path d="M1 5h3v1H1z"/><path d="M3 2H4V3H3V4H2V3H1V2H2V1H3V2Z"/></svg>',
)}")`;

// Clear over the content, solid past it.
const VIGNETTE =
  "radial-gradient(ellipse 70% 60% at 50% 50%, transparent 25%, #000 90%)";

const scrimTop =
  "pointer-events-none absolute inset-x-0 top-0 h-1/2 bg-gradient-to-b from-black/55 to-transparent";
const scrimBottom =
  "pointer-events-none absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/55 to-transparent";

export default function Bento05() {
  return (
    // overflow-x-clip, not hidden: the glows sit 40px outside their cards and
    // the section padding is only 20px at mobile, so they'd otherwise add a
    // strip of horizontal scroll. clip doesn't make this a scroll container, so
    // position: sticky anywhere inside still works.
    <section className="relative flex w-full items-center justify-center overflow-x-clip bg-[#fafafa] px-5 py-12 sm:p-10 dark:bg-black">
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 bg-[#1C1F21]/15 dark:bg-white/15"
        style={{
          maskImage: patternUrl,
          WebkitMaskImage: patternUrl,
          maskSize: "6px 6px",
          WebkitMaskSize: "6px 6px",
        }}
      />
      {/* The pattern stays at full strength under the content; a page-coloured
          scrim, held off the centre by a radial mask, sinks it to a whisper
          everywhere else. */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 bg-[#fafafa]/80 dark:bg-black/80"
        style={{
          maskImage: VIGNETTE,
          WebkitMaskImage: VIGNETTE,
        }}
      />
      <div className="relative flex w-full flex-col items-center gap-10 sm:gap-14">
        <header className="max-w-2xl text-center">
          {/* pb-1: bg-clip-text paints only inside the padding box, so the
              "g" descender needs a sliver of room or it gets sheared off. */}
          <h2 className="bg-gradient-to-b from-[#18181B] to-[#71717A] bg-clip-text pb-1 text-3xl font-semibold tracking-tight text-balance text-transparent sm:text-4xl dark:from-[#F9FAFB] dark:to-[#949495]">
            An AI-Native Studio, Engineered to Ship
          </h2>
          <p className="mt-3 text-pretty text-sm text-zinc-500 sm:text-base dark:text-zinc-400">
            D2 Studio pairs a real design system with applied AI and a typed,
            realtime backend, so an idea reaches production in weeks and stays
            cheap to change after launch.
          </p>
        </header>

        {/* The 1049px Figma reference scaled up 15% (1206px); the gutter
            follows on the spacing scale, 36 -> 40px, rather than the exact
            41px the ratio asks for. At lg the two wide cards stack in
            column one and the tall pair spans both rows; below that it
            folds to two columns, then one. The SVGs cover, so the tall
            cards just crop. */}
        <LoadInGroup className="grid w-full max-w-[1206px] grid-cols-1 gap-6 sm:grid-cols-2 sm:gap-8 lg:grid-cols-[672fr_314fr_314fr] lg:gap-10">
          {/* One column at mobile: at the Figma 672/313 the card is only ~156px
              tall, which the copy alone fills — so it goes to 3/2 and the SVG
              crops the sides. The glyph is `slice` too and its ink stops well
              inside the 672 box, so it survives the crop. */}
          <div className="relative aspect-[3/2] sm:aspect-[672/313] sm:col-span-2 lg:col-span-1">
            <Glow delay={0} card={1} />
            <LoadIn delay={0} className={cell}>
              <Flat>
                <CardArt1 {...fill} />
              </Flat>
              <Glyph d={GLYPH_16} id="glyph-16" transform={GLYPH_16_AT} />
              <div className={scrimBottom} />
              <CardCopy
                className="bottom-0"
                title="16+ AI products in Production"
                sub="Copilots, retrieval search and agent workflows shipped end to end, from the first Figma frame to the deploy that carries real traffic."
              />
            </LoadIn>
          </div>

          {/* One column, one shape: below sm the tall pair takes the wide
              cards' 3/2 so the four read as one stack rather than two
              formats. Between sm and lg it is 3/4, not the Figma
              314/654: that ratio is for a 314px column, and at half a
              tablet it is a 400px column, so the same numbers come out
              830px tall — a screen of artwork with the content at
              either end. The Figma proportion only applies at lg,
              where the pair spans two rows and takes its height from
              the grid anyway. */}
          <div className="relative aspect-[3/2] sm:aspect-[3/4] lg:row-span-2 lg:aspect-auto">
            <Glow delay={0.12} card={3} />
            <LoadIn delay={0.12} className={cell}>
              {/* Dark, already saturated: light, not colour. */}
              <Flat boost="brightness(1.16)">
                <CardArt3 {...fill} />
              </Flat>
              <div className={scrimTop} />
              <CardCopy
                className="top-0"
                title="Global by default"
                sub="Realtime Convex data on the edge, so every region reads in milliseconds."
              />
              {/* The sphere, or below lg the numbers it carries — it does its
                  own framing, which is not the same framing in the two
                  cases. */}
              <Globe />
            </LoadIn>
          </div>

          <div className="relative aspect-[3/2] sm:aspect-[3/4] lg:row-span-2 lg:aspect-auto">
            <Glow delay={0.24} card={4} />
            <LoadIn delay={0.24} className={cell}>
              {/* The brightest of the four and the flattest: colour, not light. */}
              <Flat boost="saturate(1.35) brightness(1.14)">
                <CardArt4 {...fill} />
              </Flat>
              <CardGlow texture="grain" />
              <div className={scrimTop} />
              <CardCopy
                className="top-0"
                title="Zero to production, fast"
                sub="Design system, typed API and CI wired up on day one."
              />
            </LoadIn>
          </div>

          <div className="relative aspect-[3/2] sm:aspect-[672/313] sm:col-span-2 lg:col-span-1">
            <Glow delay={0.36} card={2} />
            <LoadIn delay={0.36} className={cell}>
              <Flat boost="saturate(1.12) brightness(1.16)">
                <CardArt2 {...fill} />
              </Flat>
              <CardGlow texture="stripes" />
              <Glyph d={GLYPH_AI} id="glyph-ai" />
              <div className={scrimBottom} />
              <CardCopy
                className="bottom-0"
                title="AI woven through the stack"
                sub="Model routing, evals and guardrails built into the product from day one, not bolted on once it is already live."
              />
            </LoadIn>
          </div>
        </LoadInGroup>
      </div>
    </section>
  );
}

/* Bento 05 — the ambient card light, and the only CSS in the block that Tailwind
   cannot express: registered properties and keyframes. Everything is prefixed
   b5- and nothing here is a bare element or utility selector, so dropping the
   file into a project touches nothing but this block. Imported by
   bento-05.tsx, so it arrives with the component rather than needing a line in
   the host's globals.css.

   The field decides which of the card's own grain / stripes are lit;
   card-glow.tsx supplies the shapes, these move them.
   Long loops on purpose — the point is that you never catch the card repeating,
   so the periods are deliberately not multiples of each other.

   Every card runs two animations, never one: the motion, and an on/off gate
   over the top on a period that shares no factor with it. The card lights,
   holds, goes dark, comes back somewhere else in the motion loop. That's what
   keeps it from reading as a screensaver — and it means the gate is the one
   knob for how present a card's light is, independent of how it moves. */

/* Rippling: rings going out from the strike, like a drop landing in water.

   The radius is a registered property the gradient reads, rather than the
   mask's own size. Two reasons, both of which the size approach fails:
   the ring stays a true circle (mask-size would stretch it to the card's
   aspect), and the origin holds still at the bolt instead of the card's middle
   — a percentage mask-position only stays put at 50% 50%, so a growing box
   would drag any other origin along with it.

   The layer is a double ring, not a single one: a main front at the radius and
   a second behind it at a fixed gap, both in the one gradient. Putting the pair
   in a single gradient means they cannot drift out of sync, since there is only
   one radius driving them, and it costs one layer's worth of raster for two
   circles.

   Both are drawn thin and hard-shouldered. This is a signal going out, not
   water — an alert ping reads by its edge, and the soft wide crest that made it
   look like a drop is exactly what has to go.

   Stops are offsets around that radius, not multiples of it, so both fronts
   keep one thickness the whole way out. A wave front doesn't get fatter as it
   travels; one that does reads as a blur, not a ripple. Soft on both sides,
   softer ahead than behind.

   Percentages resolve against the distance to the farthest corner, and from an
   origin down at 62% that corner is a long way past the near edges — the sides
   sit at roughly a third of it. So the front stops at 92%: everything the eye
   is actually on has been crossed by then, and the rest of the trip would be
   the ring crawling off-card while the period ran out. It scales with the card
   either way, which a pixel radius wouldn't.

   Eased out, but only moderately. The ping still leaves the origin quicker than
   it arrives, which is the character; push the curve any harder and every ring
   is at 80%+ within a third of its life, so all four pile up at the rim and the
   card reads as one flickering edge instead of a field of rings. The curve has
   to leave them spread across the radius.

   One wave per cycle, back to back. Travel and fade run the full length of the
   period, so the next leaves the pin exactly as the last one clears the card —
   no hold, no dead frame. The period is the wave's own crossing time and
   nothing more, which is why it's 4.5s: that's how long the crossing took when
   there was still silence after it. Same wave, same speed, just no wait. */
@property --b5-r {
  syntax: "<percentage>";
  initial-value: 0%;
  inherits: false;
}

.b5-ripple {
  --b5-ox: 54%;
  --b5-oy: 62%;
  --b5-peak: 0.85;
  /* Main ring width, gap back to the second, second ring width. The gap has to
     clear both half-widths or the stop list stops being monotonic and the
     trough between the two closes up — at these widths that floor is 7.75%. */
  --b5-w: 5%;
  --b5-g: 11%;
  --b5-t: 2.5%;
  -webkit-mask-image: radial-gradient(
    circle at var(--b5-ox) var(--b5-oy),
    transparent calc(var(--b5-r) - var(--b5-g) - var(--b5-t) * 1.2),
    rgba(0, 0, 0, 0.32) calc(var(--b5-r) - var(--b5-g) - var(--b5-t) * 0.5),
    rgba(0, 0, 0, 0.62) calc(var(--b5-r) - var(--b5-g)),
    rgba(0, 0, 0, 0.2) calc(var(--b5-r) - var(--b5-g) + var(--b5-t) * 0.6),
    transparent calc(var(--b5-r) - var(--b5-w) * 1.25),
    rgba(0, 0, 0, 0.3) calc(var(--b5-r) - var(--b5-w) * 0.66),
    rgba(0, 0, 0, 0.85) calc(var(--b5-r) - var(--b5-w) * 0.2),
    #000 var(--b5-r),
    rgba(0, 0, 0, 0.5) calc(var(--b5-r) + var(--b5-w) * 0.4),
    transparent calc(var(--b5-r) + var(--b5-w))
  );
  mask-image: radial-gradient(
    circle at var(--b5-ox) var(--b5-oy),
    transparent calc(var(--b5-r) - var(--b5-g) - var(--b5-t) * 1.2),
    rgba(0, 0, 0, 0.32) calc(var(--b5-r) - var(--b5-g) - var(--b5-t) * 0.5),
    rgba(0, 0, 0, 0.62) calc(var(--b5-r) - var(--b5-g)),
    rgba(0, 0, 0, 0.2) calc(var(--b5-r) - var(--b5-g) + var(--b5-t) * 0.6),
    transparent calc(var(--b5-r) - var(--b5-w) * 1.25),
    rgba(0, 0, 0, 0.3) calc(var(--b5-r) - var(--b5-w) * 0.66),
    rgba(0, 0, 0, 0.85) calc(var(--b5-r) - var(--b5-w) * 0.2),
    #000 var(--b5-r),
    rgba(0, 0, 0, 0.5) calc(var(--b5-r) + var(--b5-w) * 0.4),
    transparent calc(var(--b5-r) + var(--b5-w))
  );
  /* Matches the 0% frame, so the first paint doesn't flash before the animation
     takes over. */
  opacity: 0;
  animation: b5-ripple 4.5s cubic-bezier(0.33, 0.55, 0.45, 1) infinite;
}
@keyframes b5-ripple {
  /* Starts at the pin's own radius, not at nothing — the ring leaves the dot
     rather than materialising in the middle of it. The wrap back to this frame
     is invisible because 100% is already at zero opacity. */
  0% {
    --b5-r: 6%;
    opacity: 0;
  }
  22% {
    opacity: var(--b5-peak);
  }
  67% {
    opacity: calc(var(--b5-peak) * 0.55);
  }
  100% {
    --b5-r: 92%;
    opacity: 0;
  }
}

/* Sweeping: one band down the length of the stripes. The band is 60% of the
   card, so mask-position percentages resolve against the remaining 40% — -150%
   puts it fully off the top, 250% fully off the bottom. The easing is the whole
   character: slow in, gathering speed through the middle, slow out again, so it
   arrives and leaves rather than scrolling past at a constant rate. */
.b5-sweep {
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-size: 100% 60%;
  mask-size: 100% 60%;
  opacity: 0.4;
  animation: b5-sweep 6.5s cubic-bezier(0.8, 0, 0.2, 1) infinite;
}
@keyframes b5-sweep {
  0% {
    -webkit-mask-position: 0 -150%;
    mask-position: 0 -150%;
  }
  100% {
    -webkit-mask-position: 0 250%;
    mask-position: 0 250%;
  }
}

/* The stripes' gate. It sits on the group rather than on the layers, because
   each layer already carries its own animation-duration for its own sweep and a
   second animation there would inherit it. 11s against sweeps of 5.8–9.1s, none
   of them factors of it, so the swell lands mid-sweep as often as it lands
   between them. It dips rather than closes — the lines never all go out. */
.b5-sweep-gate {
  opacity: 0.55;
  animation: b5-sweep-gate 11s ease-in-out infinite;
}
@keyframes b5-sweep-gate {
  0%,
  100% {
    opacity: 0.55;
  }
  20% {
    opacity: 1;
  }
  64% {
    opacity: 1;
  }
  83% {
    opacity: 0.65;
  }
}

/* The pin. A small soft dot held at the origin, breathing on the same period
   the rings leave on — this is the part that makes the card read as marking a
   location rather than as rings for their own sake. Rings alone are an effect;
   rings with a source are a signal, and the eye goes to the source. It never
   goes fully out, because the thing being pointed at doesn't stop existing
   between pulses. */
.b5-pin {
  -webkit-mask-image: radial-gradient(
    circle at var(--b5-ox) var(--b5-oy),
    #000 0%,
    rgba(0, 0, 0, 0.55) 4%,
    transparent 11%
  );
  mask-image: radial-gradient(
    circle at var(--b5-ox) var(--b5-oy),
    #000 0%,
    rgba(0, 0, 0, 0.55) 4%,
    transparent 11%
  );
  opacity: 0.55;
  animation: b5-pin 4.5s ease-in-out infinite;
}
@keyframes b5-pin {
  0%,
  100% {
    opacity: 0.5;
  }
  22% {
    opacity: 0.92;
  }
}

/* Still, but not dark: the field parks where it opens, so the texture keeps a
   little light instead of the card going flat. */
@media (prefers-reduced-motion: reduce) {
  .b5-ripple,
  .b5-pin,
  .b5-sweep,
  .b5-sweep-gate {
    animation: none;
    opacity: 1;
  }
  /* The pin stays lit and one ring parks mid-flight around it, so the card
     still reads as marking the spot. The other rings would only stack more
     light on the same still frame, so they stay out of it. */
  .b5-pin {
    opacity: 0.7;
  }
  .b5-ripple {
    --b5-r: 55%;
    opacity: 0;
  }
  .b5-ripple:first-of-type {
    opacity: 0.6;
  }
  .b5-sweep {
    opacity: 0.4;
    -webkit-mask-position: 0 50%;
    mask-position: 0 50%;
  }
}

import type { SVGProps } from "react";
const CardArt2 = (props: SVGProps<SVGSVGElement>) => (
  <svg
    width={672}
    height={313}
    viewBox="0 0 672 313"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    xmlnsXlink="http://www.w3.org/1999/xlink"
    {...props}
  >
    <g clipPath="url(#clip0_1305_19275)">
      <rect width={672} height={313} rx={24} fill="#1C1A41" />
      <g
        filter="url(#filter0_f_1305_19275)"
        style={{
          mixBlendMode: "darken",
        }}
