    '<linearGradient id="f" gradientUnits="userSpaceOnUse" x1="0" y1="349" x2="0" y2="652.5">' +
    '<stop offset="0" stop-color="#fff"/>' +
    '<stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>' +
    `<path d="${BOLT_D}" fill="url(#f)"/></svg>`,
