    return [
      `transparent ${r - RING_HALF}px`,
      `#f3f3f3 ${r - RING_HALF}px`,
      `#f3f3f3 ${r + RING_HALF}px`,
      `transparent ${r + RING_HALF}px`,
    ];
  })
  .join(", ")}, transparent 100%)`;

// One band, long and soft, running down a line.
const BAND =
  "linear-gradient(to bottom, transparent 0%, rgba(0,0,0,.7) 35%, #000 50%, rgba(0,0,0,.7) 65%, transparent 100%)";

// --- the AI card's stripes -------------------------------------------------
//
// Lines light one at a time, not as a wall. Each bar in the pattern is assigned
// to one of five layers, and a layer is a sweep of its own with its own duration
// and phase — so the light is running down some lines while others are still
// dark, and no two lines are ever quite in step. One bar in the repeat is
// assigned to nothing and never lights at all: the dropped line.
//
// Grouped into layers rather than one element per line, because at this period
// the card carries a few hundred bars and a few hundred animating elements is a
// real cost for an effect whose whole job is to look irregular. Eight bars and
// five layers does it with ten elements, and the repeat is long enough that the
// grouping doesn't read as a grouping.
// Even indices are the 1.0-alpha bars, odd the 0.3 ones, so the mapping spreads
// both across the layers — a layer that drew only faint bars would read as a
// sweep that never quite lights rather than as one more line out of step.
const STRIPE_LAYER = [0, 3, 1, 0, 2, 4, -1, 1];

// Deliberately not multiples of each other — shared factors would let the
// layers fall back into step every few cycles, which is exactly the wall the
// individual lines are meant to break up.
const STRIPE_SWEEP = [
  { dur: "6.5s", delay: "0s" },
  { dur: "7.9s", delay: "-2.3s" },
  { dur: "5.8s", delay: "-4.1s" },
  { dur: "9.1s", delay: "-1.2s" },
  { dur: "7.2s", delay: "-5.6s" },
];

// Bar i sits in tile i>>1, at x 6 or 22 within that tile, at alpha 1.0 or 0.3 —
// the pair the export paints, where the pair is the rhythm and a single bar per
// period would read as half the stripes missing. Eight bars is four 32-unit
// tiles, so the repeat is 4x one texture period.
const STRIPE_SIZE = `${1.0715 * 4}% 100%`;
const stripeTile = (layer: number) =>
  tile(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 1" preserveAspectRatio="none">' +
      STRIPE_LAYER.map((l, i) =>
        l === layer
          ? `<rect x="${(i >> 1) * 32 + (i & 1 ? 22 : 6)}" width="4" height="1" fill="#000"${i & 1 ? ' opacity=".3"' : ""}/>`
          : "",
      ).join("") +
      "</svg>",
  );

// The artwork is dark in both themes, so the light is added in both — and it is
// the same light in both, the blue ramp.
//
// It used to read --d2-blue-gradient, which looks like the right token and is
// not: the house defines it holographic (purple -> magenta -> orange) at :root
// and blue only under .dark, so the card's waves came up magenta on the pale
// theme and blue on the dark one. The artwork underneath does not change between
// themes, so neither should the light falling on it.
//
// --b5-lit is the override hook instead: block-scoped, unset by default, so a
// project that wants its own ramp sets one value and gets it in both themes
// rather than inheriting a token that flips underneath it.
const lit = {
  background:
    "var(--b5-lit, linear-gradient(135deg, oklch(0.82 0.105 235.7) 0%, oklch(0.8303 0.1245 219.879) 50%, oklch(0.899 0.059 233.6) 100%))",
} as const;

export default function CardGlow({ texture }: { texture: Texture }) {
  // The grain needs a canvas, so it arrives on the pass after mount — the same
  // deal the bolt card itself makes for it.
  const [grain, setGrain] = useState("");
  const still = useStill();
  useEffect(() => {
    if (texture === "grain" && !still) setGrain(`url("${grainTile()}")`);
  }, [texture, still]);

  // Every layer here exists to move. Still, the stripes have nothing to show —
  // the light is the effect — and the bolt keeps the rings it stands on, which
  // are a static gradient and cost a paint once. No grain canvas either.
  if (still)
    return texture === "stripes" ? null : (
      <div
        aria-hidden
        className={`pointer-events-none opacity-40 mix-blend-overlay ${ART}`}
        style={{ ...HOLE_FIT, background: RINGS }}
      />
    );

  if (texture === "stripes")
    return (
      <div
        aria-hidden
        className="b5-sweep-gate pointer-events-none absolute inset-0 mix-blend-plus-lighter"
      >
        {STRIPE_SWEEP.map((s, i) => (
          <div
            key={i}
            className="b5-sweep absolute inset-0"
            style={{
              maskImage: BAND,
              WebkitMaskImage: BAND,
              animationDuration: s.dur,
              animationDelay: s.delay,
            }}
          >
            <div
              className="absolute inset-0"
              style={{
                maskImage: stripeTile(i),
                WebkitMaskImage: stripeTile(i),
                maskSize: STRIPE_SIZE,
                WebkitMaskSize: STRIPE_SIZE,
                ...lit,
              }}
            />
          </div>
        ))}
      </div>
    );

  // What every layer lights: the card's own grain. No texture yet means the
  // grain hasn't been drawn, and an empty mask-image would paint the field
  // solid, so the layer waits a frame for it.
  const grainLayer = (
    <div
      className="absolute inset-0"
      hidden={!grain}
      style={{
        maskImage: grain,
        WebkitMaskImage: grain,
        maskSize: GRAIN_SIZE,
        WebkitMaskSize: GRAIN_SIZE,
        ...lit,
      }}
    />
  );

  // Both passes draw the same pin and the same rings off the same delays, so
  // they stay in step without anything having to keep them there.
  const signal = (
    <>
      {/* The source, first — everything after it is what leaves it. */}
      <div
        className="b5-pin absolute inset-0"
        style={RIPPLE_ORIGIN as CSSProperties}
      >
        {grainLayer}
      </div>
      {RIPPLES.map((delay, i) => (
        <div
          key={i}
          className="b5-ripple absolute inset-0"
          style={{ ...RIPPLE_ORIGIN, animationDelay: delay } as CSSProperties}
        >
          {grainLayer}
        </div>
      ))}
    </>
  );

  return (
    <>
      {/* The rings, under everything. Overlay rather than a flat stroke, so
          they lift the artwork they cross instead of drawing a grey line over
          it — the card's own colour still reads through each hairline. Held out
          of the bolt by the cutout, which is what makes them read as behind. */}
      <div
        aria-hidden
        className={`pointer-events-none opacity-40 mix-blend-overlay ${ART}`}
        style={{ ...HOLE_FIT, background: RINGS }}
      />
      {/* The card: added light, which is what the dark artwork wants. */}
      <div
        aria-hidden
        className={`pointer-events-none mix-blend-plus-lighter ${ART}`}
      >
        {signal}
      </div>
      {/* The bolt: the same fronts, tinting instead of adding. Full strength —
          the ring band is thin and the grain inside it is fine, so what lands on
          the metal is a swing of about 77/255 at the crest and nothing at all
          either side of it. Dialled back it just disappeared into the artwork. */}
      <div
        aria-hidden
        className={`pointer-events-none mix-blend-multiply ${ART}`}
        style={BOLT_FIT}
      >
        {signal}
      </div>
    </>
  );
}

"use client";

// The card art, below lg, as a bitmap instead of a live filter graph.
//
// Each export is eighteen gaussian blurs and as many blend groups, and those are
// not paid once: a browser re-runs the whole graph every time it re-rasters the
// tile the card sits on, which on a phone is every time the section is scrolled
// away from and back. Measured on the 390px layout, with the grid on screen and
// a re-raster forced each frame: 63ms median and 111ms at the worst live, 13ms
// once it is a bitmap. The draw costs ~20ms, once, and it is the only frame that
// pays it.
//
// Nothing is lost by freezing it. Below lg the artwork never moves — no
// entrance, no ambilight, no ripple — and it is the same dark art in both
// themes, so a still picture of it is the picture. Above lg this is a
// passthrough: the desktop keeps the live SVG, which is what its ambilight
// samples and what its entrance animates.
//
// A canvas rather than an <img> of the same SVG. That was the lazier version and
// it was tried: an SVG image re-runs its filters on every raster too, so it
// measured no better than the inline SVG it replaced. The bitmap is the point.

import { useEffect, useRef, useState, type ReactNode } from "react";

import { useStill } from "./load-in";

// One card rasterises at a time, page-wide. The four hosts observe in the same
// frame, so left alone all four decodes are in flight together and the peak is
// four filter graphs' worth of surfaces rather than one. Sequential costs a few
// frames on a page that is already a still picture, and takes the peak to a
// quarter — which on iOS is the difference between a load and a tab kill.
let queue = Promise.resolve();

// A per-card grade, baked into the bitmap rather than hung off it as a CSS
// filter: the draw happens once, so the card carries a graded picture and the
// compositor never sees a filter at all.
//
// It is a phone-only correction and it is per card because the exports do not
// sit at the same place. Measured off the rasters (mean luma / mean saturation
// over the cell): 16+ 66/0.61, globe 63/0.77, bolt 108/0.42, AI 88/0.59. The
// bolt is the one that reads dullest and it is not dark — it is the brightest of
// the four and the least saturated, so it wants colour, not light. The globe
// wants the opposite. 16+ is the one the eye is happy with, so it is the
// reference and takes nothing.
export default function Flat({
  boost,
  children,
}: {
  boost?: string;
  children: ReactNode;
}) {
  const host = useRef<HTMLDivElement>(null);
  const [flat, setFlat] = useState(false);
  const still = useStill();

  useEffect(() => {
    const box = host.current;
    const svg = box?.querySelector<SVGSVGElement>(":scope > svg");
    if (!still || !box || !svg) return;

    let live = true;
    let frame = 0;
    let dirty = true;
    const canvas = document.createElement("canvas");
    canvas.setAttribute("aria-hidden", "true");
    canvas.className = "absolute inset-0 h-full w-full";
    const img = new Image();

    const draw = async () => {
      const { width, height } = box.getBoundingClientRect();
      if (!width || !height) return;
      // 2 is the ceiling on purpose. The art is blurred gradient nearly
      // everywhere and blur has no detail to lose; the one crisp thing in it is
      // the 1px border, which is all a third device pixel would buy. Four
      // canvases at 3x is memory a phone has better uses for.
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const [w, h] = [Math.round(width * dpr), Math.round(height * dpr)];
      if (!dirty && canvas.width === w && canvas.height === h) return;
      dirty = false;

      // xMidYMid slice, by hand: the smallest box of the artwork's own aspect
      // that covers the cell, centred — the framing the SVG already does, so the
      // crop is the crop it already had.
      const art = svg.viewBox.baseVal;
      const s = Math.max(w / art.width, h / art.height);
      const [dw, dh] = [Math.round(art.width * s), Math.round(art.height * s)];

      // Serialised at the size it will be drawn at, not at its natural 672x313.
      // An SVG image rasterises at its own width/height and drawImage then
      // resamples, which is bilinear mush over a halftone this fine — the dots
      // are the one part of this artwork with detail to lose. Sized up front it
      // rasterises vector-crisp and the draw is a 1:1 blit.
      const clone = svg.cloneNode(true) as SVGSVGElement;
      clone.setAttribute("width", `${dw}`);
      clone.setAttribute("height", `${dh}`);
      img.src =
        "data:image/svg+xml;charset=utf-8," +
        encodeURIComponent(new XMLSerializer().serializeToString(clone));
      await img.decode();
      if (!live) return;

      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        // Safari only got ctx.filter in 17. Where it is missing the assignment
        // is a no-op and the card draws ungraded, which is the picture this file
        // already shipped — so no fallback beyond letting it happen.
        if (boost) ctx.filter = boost;
        ctx.drawImage(img, (w - dw) / 2, (h - dh) / 2);
      }
      // Appended before the SVG is hidden, so there is no frame with neither.
      if (!canvas.isConnected) box.appendChild(canvas);
      setFlat(true);
    };

    const invalidate = () => {
      dirty = true;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        queue = queue.then(draw).catch(() => {});
      });
    };

    // Fires once on observe, so this is also the initial draw. After that the
    // only thing that changes the box is an orientation change, and a frame's
    // coalescing keeps a rotation from redrawing four times.
    const ro = new ResizeObserver(invalidate);
    ro.observe(box);

    // The art is not necessarily finished when it first mounts: c4's grain is
    // generated in the browser and lands a render later, and rasterising before
    // it arrives bakes a card with no grain on it. Watching the subtree catches
    // that without this file having to know which card does it. It goes quiet
    // once the art settles, and the redraw is the same coalesced one.
    // The SVG is hidden by a class on the host rather than by its own style
    // attribute, so this observer never sees its own effect.
    const mo = new MutationObserver(invalidate);
    mo.observe(svg, { attributes: true, childList: true, subtree: true });

    return () => {
      live = false;
      cancelAnimationFrame(frame);
      ro.disconnect();
      mo.disconnect();
      canvas.remove();
      setFlat(false);
    };
  }, [still, boost]);

  // position: absolute with z-index auto is not a stacking context, so the
  // wrapper is invisible to everything painting over it — the glyph, the scrims
  // and the card glow's blends all see the same backdrop they saw before.
  //
  // max-lg hides the SVG from the document's first paint, not from `flat` — and
  // that, not the canvas, is what this file is really for. Freezing the artwork
  // saved the re-rasters, but the phone still paid for the live graph once,
  // before the canvas landed, at full devicePixelRatio: the exports' filter
  // regions run to 3.5x their own viewBox, so on a 390px card at dpr 3 a single
  // gaussian is a 4135x1849 surface (~30MB) and the four cards' eighteen come to
  // ~680MB of them. iOS kills the tab for it — "A problem repeatedly occurred",
  // Safari and Chrome alike, since both are WebKit there. A media query rather
  // than `still`, because it has to be right in the server's HTML: any JS-set
  // flag is a decision taken after that HTML has already painted.
  //
  // The serialised clone still rasterises from a display:none source — the
  // filters run inside the SVG image, which has its own rendering pass — so the
  // canvas is unchanged, and it is drawn at dpr 2, a quarter the area.
  //
  // Reduced motion on a desktop is `still` too and keeps the live SVG: it is
  // above lg, so max-lg does not fire and `flat` swaps it as before.
  return (
    <div
      ref={host}
      className={`absolute inset-0 max-lg:[&>svg]:hidden ${flat ? "[&>svg]:hidden" : ""}`}
    >
      {children}
    </div>
  );
}

"use client";

// Cobe globe for the "Global by default" card.
//
// Pinned to cobe 0.6.x, because 2.0.1 renders the sphere but never draws the
// land dots, even on its own README config.
//
// The canvas is `mix-blend-mode: screen` so the globe composites onto the card
// artwork instead of sitting on top of it: the near-black sphere body drops out
// and only the land dots, the terminator and the glow add light to the gradient.
// That only works with a dark render, hence dark:1 + a very low baseColor.
//
// cobe centres and scales the sphere against the width/height it is handed, in
// device pixels, while the backing buffer follows the canvas element's own box.
// The two have to agree: hand it a fixed size and the sphere lands off-centre and
// at the wrong scale. So the element is measured, and re-measured on resize.

import createGlobe from "cobe";
import {
  Building2,
  Castle,
  Drum,
  FerrisWheel,
  Landmark,
  RadioTower,
  Sailboat,
  Ship,
  TowerControl,
  TreePalm,
} from "lucide-react";
import {
  animate,
  useInView,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

import { light, useLit, useWide } from "./load-in";

const { sin, cos, sqrt, PI } = Math;

const THETA = 0.2;
const SAMPLES = 16000;

type Vec = [number, number, number];

// cobe's marker vector: lat/lng -> unit sphere, with lng offset by a half turn.
function world(lat: number, lng: number): Vec {
  const la = (lat * PI) / 180;
  const lo = (lng * PI) / 180 - PI;
  const cl = cos(la);
  return [-cl * cos(lo), sin(la), cl * sin(lo)];
}

// The shader paints a marker on the nearest dot of its Fibonacci lattice, not at
// the exact lat/lng, so a chip placed on the true coordinate misses the dot it
// belongs to by up to ~5px at this card's globe size. Snap to the same lattice.
//
// One sweep of the lattice for the whole list, not one per city: the lattice
// point is the expensive part (three trig calls) and it does not depend on which
// city is being matched, so walking the cities inside the sweep pays for it once
// instead of ten times. Measured, that is the module's load cost down from 14ms
// to ~2ms — small on a desk, but it is synchronous work on the critical path and
// a phone pays several times that.
function snapAll(targets: Vec[]): Vec[] {
  const best = targets.slice();
  const bd = targets.map(() => Infinity);
  for (let j = 0; j <= SAMPLES; j++) {
    const zj = 1 - (2 * j) / SAMPLES;
    const l = sqrt(1 - zj * zj);
    const k = ((j * 0.618034) % 1) * 2 * PI;
    const p: Vec = [cos(k) * l, zj, sin(k) * l];
    targets.forEach(([x, y, z], i) => {
      const d = (p[0] - x) ** 2 + (p[1] - y) ** 2 + (p[2] - z) ** 2;
      if (d < bd[i]) [bd[i], best[i]] = [d, p];
    });
  }
  return best;
}

// The cobe site's "Analytics" showcase: live visitor counts per city with a
// trend delta, green markers. Its own version positions the chips with CSS
// anchor positioning, which needs cobe 2.x and is Chrome-only, so the chips
// here ride the projection below instead.
// London, Paris and Berlin sit within a few degrees of each other, so on a card
// this narrow their chips land on top of one another. Sydney is below the
// card's window entirely. All ten stay as markers; only the ones whose chips
// never collide, checked pairwise over a full rotation, get a chip.
const CITIES = [
  {
    city: "New York",
    icon: Building2,
