  },
  {
    city: "Singapore",
    icon: Sailboat,
    visitors: 296,
    trend: 4,
    chip: true,
    location: [1.35, 103.82],
  },
  {
    city: "Lagos",
    icon: Drum,
    visitors: 224,
    trend: 18,
    chip: true,
    location: [6.52, 3.38],
  },
  {
    city: "Sydney",
    icon: Ship,
    visitors: 201,
    trend: 15,
    chip: false,
    location: [-33.87, 151.21],
  },
  {
    city: "Berlin",
    icon: Castle,
    visitors: 178,
    trend: -1,
    chip: false,
    location: [52.52, 13.41],
  },
];

const VECS = snapAll(CITIES.map((c) => world(c.location[0], c.location[1])));

// The shader rotates the view ray by mat3 L(theta, phi); applying the same
// rotation forward puts a world point in view space. The sphere fills 0.8 of the
// half-box, and z > 0 is the front hemisphere.
function project([wx, wy, wz]: Vec, phi: number) {
  const [ct, st, cp, sp] = [cos(THETA), sin(THETA), cos(phi), sin(phi)];
  return {
    x: cp * wx + sp * wz,
    y: sp * st * wx + ct * wy - cp * st * wz,
    z: -sp * ct * wx + st * wy + cp * ct * wz,
  };
}

// What the card is actually saying, for a screen that cannot afford to say it
// with a sphere. Booting cobe compiles its fragment shader — ~3s of blocked main
// thread on a browser that has never compiled it, per the note below — onto a
// canvas 2.5x the card, and that is the page's single worst moment on a phone.
// The chips were always the payload; the globe was the frame around them. So
// below lg the frame goes and the chips stay, as a table.
//
// Static: no entrance, no counting up. Same numbers, same mono, same greens as
// the chips the sphere carries, so the two read as one component at two sizes.
function Stats() {
  return (
    <div
      aria-hidden
      className="absolute inset-x-4 bottom-4 flex flex-col sm:inset-x-5 sm:bottom-5"
    >
      {CITIES.filter((c) => c.chip).map((c, i) => (
        // A deck, not a table: each row is its own card and each one tucks a
        // few pixels under the one before it, so the column reads as cards laid
        // down rather than rules drawn across the artwork. The overlap only
        // ever eats padding — the extra pt is exactly what the -mt takes back —
        // so every row stays clear of the card above it. Later rows paint over
        // earlier ones by document order, which is the direction a hand of
        // cards fans, so no z-index is needed.
        //
        // The fill is solid, not glass: no tint over the artwork and no
        // backdrop-blur. Seven blurred panels over artwork is the sort of thing
        // this section is being pulled back from, and a translucent row picks
        // up whatever gradient happens to be behind it, so the deck changed
        // colour down its own length. One opaque ramp — the Figma one, EEEEEE
        // -> D1D1D1 -> B4B4B4 top to bottom — and every row runs it identically,
        // so they read as one stack of the same object lit from above. Dark mode
        // runs the same ramp inverted into the card's own blue-black, with the
        // shadows opened up: at light-mode alphas they vanish into it.
        //
        // 8px radius, not the 12 it had: the deck sits 16px inside a card
        // rounded at 24, and concentric corners want inner = outer - inset.
        //
        // Below sm the deck also fans — each row a step wider than the one it
        // tucks under, so three rows read as cards laid down in perspective
        // rather than a list. Only below sm: from sm up the card is tall and
        // carries all seven, and seven steps of that is a wedge.
        //
        // Nothing here waits for anything, and an entrance was tried and taken
        // back out: it started the rows at opacity 0 and turned them on from an
        // IntersectionObserver, and that observer sits inside a
        // content-visibility: auto subtree, whose contents a browser is free
        // not to report. Where it never fired, the starting state was what
        // stayed — a blank card. On a screen this size these numbers are the
        // card's whole content, so nothing about them is conditional.
        // Below sm the card is the wide cards' 3/2 and has room for three, so
        // the tail of the list is dropped rather than squeezed — in CSS, since
        // the cutoff is the card's shape and nothing else knows it.
        <div
          key={c.city}
          className={`-mt-3 flex items-center gap-2.5 rounded-lg bg-linear-to-b from-[#EEEEEE] via-[#D1D1D1] to-[#B4B4B4] pt-5.5 pr-4 pb-2.5 pl-3 shadow-[-1px_-2px_6px_rgba(0,0,0,0.20),0_2px_4px_-1px_rgba(0,0,0,0.15),0_8px_16px_-4px_rgba(0,0,0,0.21)] first:mt-0 first:pt-2.5 dark:from-[#1F242E] dark:via-[#13171E] dark:to-[#080A0E] dark:shadow-[-1px_-2px_6px_rgba(0,0,0,0.45),0_2px_4px_-1px_rgba(0,0,0,0.35),0_8px_16px_-4px_rgba(0,0,0,0.50)] ${
            i > 2 ? "max-sm:hidden" : ["max-sm:mx-6", "max-sm:mx-3", ""][i]
          }`}
        >
          {/* The city, not a status light: a landmark reads at 14px and says
              which place the row is without the name having to be read. */}
          <c.icon
            className="size-3.5 shrink-0 text-[#1C1F21]/45 dark:text-white/45"
            strokeWidth={1.75}
          />
          <span className="truncate text-xs text-[#1C1F21]/70 dark:text-white/70">
            {c.city}
          </span>
          <span className="ml-auto font-mono text-[0.85rem] leading-none font-semibold tracking-[-0.02em] text-[#1C1F21] dark:text-white">
            {c.visitors}
          </span>
          {/* One pair of greens and reds per theme: the bright ones wash out on
              the light ramp, the deep ones go muddy on the dark one. */}
          <span
            className={`w-11 shrink-0 text-right font-mono text-[0.55rem] leading-none font-medium tracking-[0.02em] ${
              c.trend >= 0
                ? "text-[#059669] dark:text-[#34D399]"
                : "text-[#DC2626] dark:text-[#F87171]"
            }`}
          >
            {c.trend >= 0 ? "↑" : "↓"} {Math.abs(c.trend)}%
          </span>
        </div>
      ))}
    </div>
  );
}

// The sphere below lg is never mounted, not hidden: a hidden canvas still boots.
export default function Globe() {
  return useWide() ? <Sphere /> : <Stats />;
}

function Sphere() {
  const ref = useRef<HTMLCanvasElement>(null);
  const labels = useRef<(HTMLDivElement | null)[]>([]);

  // Booting the globe compiles cobe's fragment shader, and on a browser that has
  // never compiled it that is ~3s of blocked main thread — measured, and paid
  // once per profile: every later visit hits Chrome's program cache and boots in
  // ~20ms. Left to the card's own crossing, that one stall lands on the exact
  // frames the section is scrolling in, which is the worst place in the page for
  // it. So it is spent at idle after mount instead, while the reader is still on
  // the hero and nothing is moving — a stall nobody is scrolling through.
  //
  // The viewport gate stays as the backstop: if idle never comes (a busy main
  // thread, or a browser without requestIdleCallback past the timeout), the
  // approach still boots it. once on both, because a reader scrolling back
  // should find it already turning rather than watch it boot a second time.
  // "some", not a fraction: the canvas is deliberately far bigger than the card
  // and mostly clipped by it, so any percentage of the canvas itself is the
  // wrong measure — asking for 30% of it never comes true.
  const inView = useInView(ref, {
    once: true,
    amount: "some",
    margin: "100% 0px",
  });
  const [idle, setIdle] = useState(false);

  useEffect(() => {
    const ric = window.requestIdleCallback;
    if (!ric) {
      const t = setTimeout(() => setIdle(true), 1200);
      return () => clearTimeout(t);
    }
    const id = ric(() => setIdle(true), { timeout: 2500 });
    return () => window.cancelIdleCallback?.(id);
  }, []);

  // The sphere is on the same switch as the light: it spins up as the section
  // lights and coasts to a stop as the reader leaves, on the glow's curve and
  // its two durations. A factor on the step rather than a stop/start, so the
  // rotation eases out of its current angle instead of snapping — and the render
  // loop keeps running, since the chips still have to be placed at rest.
  const lit = useLit();
  // Read inside the render loop, which is built once and does not close over
  // the light. A zero step alone does not mean "at rest" — it is also what the
  // first frame after the light comes on sees, before the ramp has ticked.
  const litRef = useRef(lit);
  litRef.current = lit;
  const still = useReducedMotion();
  const spin = useMotionValue(0);

  // cobe hands back its Phenomenon, whose render loop is a self-rescheduling rAF
  // — it redraws the full canvas forever, on screen or not. Measured: it was
  // still drawing ~60 full frames a second with the section a screen and a half
  // away, which is the tax every other animation on the page was paying. But
  // once the spin has coasted to zero nothing in the frame changes, so the loop
  // is redrawing an identical image: park it there (below, in onRender) and wake
  // it here when the light comes back. Parking is not a stop/start of the
  // globe — no rebuild, no shader recompile, the context stays warm.
  // Typed structurally: cobe's own types name Phenomenon, but it is a
  // transitive dependency and not resolvable from here.
  const globe = useRef<{
    toggle: (on: boolean) => void;
    destroy: () => void;
  } | null>(null);

  useEffect(() => {
    globe.current?.toggle(true);
    const run = animate(spin, lit ? 1 : 0, light(lit, still));
    return () => run.stop();
  }, [lit, still, spin]);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas || !(inView || idle)) return;

    let phi = 0;
    let built = 0;

    // The globe's first composite costs in proportion to its pixels, and this
    // canvas is deliberately 2.5x the card, so the buffer is the most expensive
    // number on the page: measured, halving it took the section's worst frame on
    // entry from 3.8s to 0.9s. It was pinned at 2 regardless of the screen, which
    // on a 1x display renders four times the pixels that can ever be shown. So
    // follow the display, and cap it: past 1.5 the extra pixels land on dots that
    // are already sub-pixel, and only the stall grows.
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);

    const build = () => {
      const size = Math.round(canvas.offsetWidth * dpr);
      if (!size || size === built) return;
      built = size;
      // Fades rather than pops: the first frames land while the section is
      // still settling into view.
      canvas.style.opacity = "1";
      const [w, h] = [canvas.offsetWidth, canvas.offsetHeight];
      globe.current?.destroy();
      globe.current = createGlobe(canvas, {
        devicePixelRatio: dpr,
        width: size,
        height: size,
        phi: 0,
        theta: THETA,
        dark: 1,
        diffuse: 1.2,
        mapSamples: SAMPLES,
        mapBrightness: 7,
        baseColor: [0.08, 0.1, 0.18],
        markerColor: [0.3, 0.85, 0.45],
        glowColor: [0.14, 0.18, 0.42],
        markers: CITIES.map(({ location }) => ({
          location: [location[0], location[1]],
          size: 0.04,
        })),
        onRender: (state) => {
          state.phi = phi;
          const step = still ? 0 : spin.get();
          phi += 0.004 * step;

          CITIES.forEach((_, i) => {
            const el = labels.current[i];
            if (!el) return;
            const { x, y, z } = project(VECS[i], phi);
            // Positioned with a transform, not left/top: percentage offsets are
            // laid out, so they snap to whole pixels and the chip shivers as it
            // creeps sideways while the canvas marker moves subpixel-smooth.
            el.style.transform = `translate3d(${(x * 0.8 + 1) * 0.5 * w}px, ${
              (1 - y * 0.8) * 0.5 * h
            }px, 0) translate(-50%, -50%)`;
            // On the front face, and inside the slice of sphere the card
            // actually shows: the globe box is far wider than the card and
            // offset right, so the window is the sphere's left side, x in
            // [-0.79, -0.22] once the chip's own width is allowed for. The
            // box also sits low enough that the copy is clear of the sphere,
            // so only the bottom needs a y bound.
            // Entry/exit is a CSS transition on the flag, not a per-frame
            // opacity: transitions retarget when a marker skims the boundary,
            // where a fresh keyframe each frame would restart from zero.
            // Written only on change so the loop doesn't touch the DOM 60x/s.
            const on = z > 0.12 && x <= -0.22 && x >= -0.79 && y >= -0.49;
            if ((el.dataset.on === "true") !== on) el.dataset.on = `${on}`;
          });

          // Nothing left to move: this frame is the one the next frame would
          // draw, so stop after it. Chips included — they are placed from the
          // same phi, so a still sphere means still chips. Under reduced motion
          // that is true from the first frame; otherwise it is the light being
          // out with the spin already coasted to zero. Parking from inside
          // onRender is what phenomenon's own loop reads, so the rAF chain ends
          // here rather than one frame later.
          if (still || (!step && !litRef.current)) globe.current?.toggle(false);
        },
      });
    };

    // Fires once on observe, so this is also the initial build.
    const ro = new ResizeObserver(build);
    ro.observe(canvas);

    return () => {
      ro.disconnect();
      globe.current?.destroy();
      globe.current = null;
    };
  }, [inView, idle, still, spin]);

  // Oversized, so the card is a window onto the sphere; pushed half a card-width
  // right, so the window lands on the left limb rather than the middle. ml is a
  // % of the card, unlike translate which is a % of the (much wider) globe box.
  // Down a quarter of the card via top, not mt: percentage margins resolve
  // against the container's width even vertically. It lives here rather than in
  // the page because it is the sphere's framing, and the card's other occupant
  // wants none of it.
  return (
    <div className="pointer-events-none absolute top-3/4 left-1/2 ml-[50%] aspect-square w-[248%] -translate-x-1/2 -translate-y-1/2">
      <canvas
        ref={ref}
        aria-hidden
        className="h-full w-full opacity-0 transition-opacity duration-700 ease-out"
        style={{ mixBlendMode: "screen" }}
      />
      <div aria-hidden className="pointer-events-none absolute inset-0">
        {CITIES.map((c, i) =>
          !c.chip ? null : (
            <div
              key={c.city}
              ref={(el) => {
                labels.current[i] = el;
              }}
              data-on="false"
              className="group absolute top-0 left-0 will-change-transform"
            >
              {/* The dot leads in and trails out; the chip follows it and
                  leaves first, so the pair reads as one thing arriving.
                  Exits are quicker than entrances, and each span transitions
                  only the properties it moves — Tailwind v4 compiles scale
                  and translate to the standalone CSS properties, not to
                  `transform`, so those are what have to be named. */}
              <span className="block size-1.5 scale-50 rounded-full bg-[#4ADE80] opacity-0 shadow-[0_0_9px_2px_rgba(52,211,153,0.7)] transition-[scale,opacity] delay-[90ms] duration-[140ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-data-[on=true]:scale-100 group-data-[on=true]:opacity-100 group-data-[on=true]:delay-0 group-data-[on=true]:duration-200 motion-reduce:scale-100!" />
              <span className="absolute bottom-3.5 left-1/2 flex origin-bottom -translate-x-1/2 translate-y-[3px] scale-[0.96] items-baseline gap-1.5 rounded-[4px] bg-black/85 px-2 py-[0.3rem] whitespace-nowrap opacity-0 transition-[scale,translate,opacity] duration-[130ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-data-[on=true]:translate-y-0 group-data-[on=true]:scale-100 group-data-[on=true]:opacity-100 group-data-[on=true]:delay-[70ms] group-data-[on=true]:duration-200 motion-reduce:translate-y-0! motion-reduce:scale-100!">
                <span className="font-mono text-[0.85rem] leading-none font-semibold tracking-[-0.02em] text-white">
                  {c.visitors}
                </span>
                <span
                  className={`font-mono text-[0.55rem] leading-none font-medium tracking-[0.02em] ${
                    c.trend >= 0 ? "text-[#34D399]" : "text-[#F87171]"
                  }`}
                >
                  {c.trend >= 0 ? "↑" : "↓"} {Math.abs(c.trend)}%
                </span>
              </span>
            </div>
          ),
        )}
      </div>
    </div>
  );
}

"use client";

// The ambilight's copy of the card art, on its own so it can be left behind.
//
// The glow only ever exists above lg, but as children of <Glow> these were
// rendered on the server and serialised into the flight payload regardless — a
// second copy of all four exports, about half the document, which every phone
// downloaded and parsed in order to render none of it. Behind the ssr:false
// dynamic() in glow.tsx it is a chunk the desktop fetches after hydration and
// the phone never asks for.

import CardArt1 from "./card-art-1";
import CardArt2 from "./card-art-2";
import CardArt3 from "./card-art-3";
import CardArt4 from "./card-art-4";

const ART = { 1: CardArt1, 2: CardArt2, 3: CardArt3, 4: CardArt4 };

export type Card = keyof typeof ART;

export default function GlowArt({ card }: { card: Card }) {
  const Art = ART[card];
  return (
    <Art
      className="absolute inset-0 h-full w-full"
      preserveAspectRatio="xMidYMid slice"
    />
  );
}

"use client";

// Ambilight: the card's own artwork, blown out and blurred behind it, so the
// spill is sampled from the card instead of guessed — a card with a hot
// gradient throws a bright halo, a flat one barely glows. Screen on dark keeps
// only the light; multiply on the pale page leaves a tinted aura instead of a
// grey smudge. Blur is wide enough that the four halos pool across the section.
// It switches on when the section is on screen and off when it leaves — see
// load-in.tsx. The lit opacity is a variable so the animation has something
// theme-aware to land on; the class no longer sets it directly.
//
// will-change is pinned rather than left to Motion, which sets it for the length
// of an animation and drops it after. Dropping it de-promotes the layer, and
// re-rastering a 72px blur over saturated card art — four of them, two of which
// are card-height — is not a frame's worth of work: measured, that de-promotion
// was the section's worst frame at 170ms, and pinning it takes the whole pass to
// 24ms with no dropped frames. The blur radius is not the problem; at 24px it
// still cost 145ms. This is the case will-change is for — a layer whose opacity
// animates every time the reader passes — and the cost is the GPU memory for
// four promoted layers, held for the life of the page.
// ponytail: pinned on all four. If the memory ever matters, render the glow's
// source at a fraction of its size and scale it up — nothing under 72px of
// detail survives the blur anyway.
//
// A client component so the art below can be code-split. LoadIn returns null
// below lg, so GlowArt never renders there and its chunk is never requested.

import dynamic from "next/dynamic";

import LoadIn from "./load-in";
import type { Card } from "./glow-art";

const GlowArt = dynamic(() => import("./glow-art"), { ssr: false });

export default function Glow({ card, delay }: { card: Card; delay: number }) {
  return (
    <LoadIn
      glow
      delay={delay}
      className="pointer-events-none absolute -inset-10 mix-blend-multiply blur-[72px] saturate-150 will-change-[opacity] [--b5-glow:0.45] dark:mix-blend-screen dark:[--b5-glow:0.5]"
    >
      <GlowArt card={card} />
    </LoadIn>
  );
}

"use client";

// The grain the c4 card is dusted with, generated instead of downloaded.
//
// The Figma export shipped it as a 1024² PNG inlined as base64 — 2.1MB of
// string in the page's JS bundle. Nothing could compress it, because the file
// was a field of per-pixel random noise and the bytes *were* the randomness:
// greyscale-lossless still came to 718KB.
//
// So the image was measured rather than re-encoded, and it turned out to be one
// line of arithmetic. Two facts fell out of it:
//
//   correlation between neighbouring pixels: -0.0023, i.e. none. There is no
//   spatial structure to reproduce, only a distribution — which is why
//   feTurbulence is the wrong tool here despite being the obvious one. Perlin
//   noise is smooth by construction and tops out near a third of uncorrelated
//   noise's per-pixel contrast, so it renders visibly softer than this.
//
//   above a floor of zeros, the quantiles are dead linear — 4, 32, 60, 88, 115,
//   143, 171, 199, 227, 255, in steps of 28. A clamped uniform, in other words,
//   over a range running below zero, with 43.05% of it landing on the floor.
//
// Solving those two for the range gives the line below, which reproduces the
// original to within 0.07%: mean 72.61 against 72.66, sd 84.09 against 83.94,
// zeros 43.05% against 43.05%.
//
// The image's RGB equalled its alpha exactly, which reads as premultiplied
// white — but PNG is decoded as straight alpha, so what it actually paints is
// grey level `a` at alpha `a`, not white at alpha `a`. That distinction is the
// whole look: white at alpha `a` contributes `a` to the result where this
// contributes `a²/255`, which is a far softer dusting. Setting RGB to full
// white here instead measured 2.06 luma too bright over the card.
const SPAN = 447.8;
const FLOOR = -192.8;

// 256², to tile. The export drew its noise at 0.9 user units per pixel, so this
// spans 230.4 units and repeats about 1.4 times across the card and 3 down —
// invisible in a field this fine, where there is no structure to line up.
const TILE = 256;

// Generated once for the page, not once per card: the export renders twice, as
// the card and again as the blurred glow behind it, and one field does for
// both. Cached at module scope rather than in a hook for the same reason —
// nothing about it depends on a component.
let cached: string | undefined;

export function grainTile(): string {
  if (cached !== undefined) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = TILE;
  const image = new ImageData(TILE, TILE);

  // One 32-bit write per pixel rather than four byte writes. Measured, that is
  // the fill down from 5.6ms to under 2 — worth it for a loop this hot, and the
  // packing is the only thing it costs in clarity. Little-endian, so the bytes
  // read R,G,B,A but pack as 0xAABBGGRR — and all four channels carry the same
  // value, per the note above.
  const px = new Uint32Array(image.data.buffer);
  for (let i = 0; i < px.length; i++) {
    const a = Math.max(0, Math.random() * SPAN + FLOOR) | 0;
    px[i] = (a << 24) | (a << 16) | (a << 8) | a;
  }

  canvas.getContext("2d")!.putImageData(image, 0, 0);
  cached = canvas.toDataURL();
  return cached;
}

"use client";

// The section's entrance. Two shapes of the same beat: the card rises the last
// few pixels into place, the ambilight behind it blooms up and settles, both on
// the cell's own delay.
//
// It fires when the section is scrolled to, not when the page mounts, and the
// whole grid fires off one observer on the group rather than four of its own.
// That is what keeps the stagger a choreography: with an observer per card the
// bottom row would trip a scroll-length after the top one and the beats would
// land in whatever order the reader's scroll happened to produce. The group
// publishes both of its states on context and the cards read them, so one
// observer and one scroll reader drive the whole grid.
//
// The glow is a light switch, not part of the entrance: it comes up when the
// section is on screen and goes out when it leaves, every time — hence a
// separate state from the one-shot entrance, which happens once and stays.
//
// The cards ride the same switch at their own brightness: lit they sit at full
// strength, otherwise they sink to DIM. Same curve and same two durations as the
// glow, so the light and the cards it falls on move as one thing rather than two
// effects that happen to overlap.
//
// The glow animates its own opacity rather than a wrapper's. A wrapper at
// opacity < 1 would isolate the layer into its own stacking context and its
// mix-blend-mode would then blend against nothing instead of the page — which on
// the pale theme means the multiply drops out and the raw gradient flashes
// through for the length of the fade. So this component *is* the layer: it takes
// the layer's className rather than wrapping it.
//
// The resting value is a variable because it differs per theme (0.45 light,
// 0.5 dark); Motion resolves it off the element, so the animation lands on
// whichever value the current theme set.

import {
  motion,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
} from "motion/react";
import { createContext, useContext, useEffect, useRef, useState } from "react";
import type { ReactNode, RefObject } from "react";

type Bezier = [number, number, number, number];

const EASE: Bezier = [0.22, 1, 0.36, 1];
// The glow gets an ease-in-out instead: no edge at either end, so the light
// swells and dies rather than arriving and stopping.
const SOFT: Bezier = [0.33, 0, 0.35, 1];

// 0.15, not "some": on a phone the grid is several screens tall, and a trigger
// on the first pixel would spend the entrance off-screen. once, because a
// reader scrolling back should find the section lit, not watch it switch on
// again.
const VIEWPORT = { once: true, amount: 0.15 } as const;

// The light is on for the middle of the section's pass: 0 is the section's top
// meeting the bottom of the window, 1 its bottom leaving the top. Read as scroll
// progress rather than a visible fraction because on a phone the grid is taller
// than the window, and "40% of it is showing" is then never true.
//
// Both ends are placed by what is left to scroll, not by where the section sits:
// a power-down that starts at 0.8 has a fifth of the pass to play in, which at
// any real scroll speed is less than the ramp takes — so most of it happened to
// an empty screen. Off at 0.68 leaves a third of the pass, and the section
// visibly powers down before it goes. On is early for the same reason from the
// other side: the bloom then overlaps the cards' rise instead of arriving after
// the entrance has already finished.
const [ON, OFF] = [0.34, 0.68];

// How far the cards sink when the light is off. Deep enough to read as the
// section powering down, shallow enough that the copy stays legible on the way
// past.
const DIM = 0.72;

const Stage = createContext({ entered: false, lit: false });

// Everything in this file is a desktop luxury, and the desktop is where it is
// judged. Below lg the section is a still picture: lit cards, no entrance, no
// ambilight, no ripple, no spin. The cost it sheds is not the choreography, it
// is what the choreography keeps touching — four extra copies of artwork
// carrying eighteen SVG blur filters apiece, a 72px blur on a pinned layer, and
// a scroll listener driving all of it.
//
// False until the effect runs, so the server renders the still version. That is
// also what the phone should get first regardless: the animated path server-
// renders its cards at opacity 0, so until JS lands the section is a blank
// screen. Static-first means the artwork arrives with the document.
//
// The desktop upgrade lands a tick after hydration, above the fold of this
// section — the reader is a screen away, and the entrance is keyed to scrolling
// into it, not to mount.
// ponytail: the ambilight's artwork still rides the RSC payload as this
// component's children even where it never renders. Dropping that too means the
// glow importing the four exports itself behind an ssr:false dynamic(), which
// trades document bytes for a lazily-loaded desktop-only chunk.
export const useWide = () => {
  const [wide, setWide] = useState(false);
  useEffect(() => {
    const q = matchMedia("(min-width: 1024px)");
    const sync = () => setWide(q.matches);
    sync();
    q.addEventListener("change", sync);
    return () => q.removeEventListener("change", sync);
  }, []);
  return wide;
};

// The one question the animated parts ask. Reduced motion is folded in here
// rather than checked separately: a reader who asked for less motion and a phone
// that cannot afford it want the same still frame.
// Both hooks called, never short-circuited — || would skip the second one for as
// long as the first is false, and the count would change the moment it flips.
export const useStill = () => {
  const wide = useWide();
  const reduced = useReducedMotion();
  return !wide || !!reduced;
};

// The one switch, and the one shape of its throw: glow, card brightness and the
// globe's spin all run off these so the section powers up and down as a single
// movement. Slow both ways, slower going out.
export const useLit = () => useContext(Stage).lit;
export const light = (lit: boolean, still?: boolean | null) => ({
  duration: still ? 0.2 : lit ? 1.44 : 1.98,
  ease: SOFT,
});

// The scroll reader, as a child that draws nothing.
//
// useScroll is not free: it listens for scroll and measures its target on every
// event, and on a phone the target is a grid several screens tall. Below lg
// there is no light for it to switch — the callback was already guarded — so all
// of that was measurement in aid of a no-op. Hooks cannot be skipped, so the
// hook moves into a component that is only mounted when something reads it.
//
// A null-rendering child rather than a second branch of the group itself:
// swapping the group would change the element type at the moment `still`
// resolves, and remounting four cards' worth of artwork costs more than the
// listener it saves.
function ScrollLit({
  target,
  onChange,
}: {
  target: RefObject<HTMLDivElement | null>;
  onChange: (lit: boolean) => void;
}) {
  const { scrollYProgress } = useScroll({
    target,
    offset: ["start end", "end start"],
  });
  useMotionValueEvent(scrollYProgress, "change", (p) =>
    onChange(p >= ON && p < OFF),
  );
  return null;
}

export function LoadInGroup({
  className,
  children,
}: {
  className?: string;
  children: ReactNode;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const still = useStill();
  const [lit, setLit] = useState(false);
  const [entered, setEntered] = useState(false);

  // Still means the switch is welded on: everything downstream reads lit and
  // entered, so one pair of values makes the whole section a lit still frame
  // without a second code path in any of the four cards.
  return (
    <Stage.Provider value={{ entered: entered || still, lit: lit || still }}>
      {/* The entrance observer goes the same way as the scroll reader:
                still means `entered` is already true, so the IntersectionObserver
                would fire once to set a value nothing reads. Dropped as props
                rather than by swapping the element, for the same remount reason. */}
      <motion.div
        ref={ref}
        className={className}
        {...(still
          ? {}
          : {
              viewport: VIEWPORT,
              onViewportEnter: () => setEntered(true),
            })}
      >
        {!still && <ScrollLit target={ref} onChange={setLit} />}
        {children}
      </motion.div>
    </Stage.Provider>
  );
}

export default function LoadIn({
  className,
  delay = 0,
  glow = false,
  children,
}: {
  className?: string;
  delay?: number;
  glow?: boolean;
  children: ReactNode;
}) {
  const wide = useWide();
  const reduced = useReducedMotion();
  const still = !wide || !!reduced;
  // Every glow and every card follows the one switch on the group, so the four
  // come up together rather than each on its own card's crossing.
  const { entered, lit } = useContext(Stage);
  const sweep = light(lit, still);

  if (glow) {
    // No ambilight below lg. Reduced motion keeps it — a halo is not motion,
    // its fade is — so it comes on and stays on.
    if (!wide) return null;
    return still ? (
      <div
        aria-hidden
        className={className}
        style={{ opacity: "var(--b5-glow)" }}
      >
        {children}
      </div>
    ) : (
      <motion.div
        aria-hidden
        className={className}
        initial={false}
        animate={{ opacity: lit ? "var(--b5-glow)" : 0 }}
        transition={sweep}
      >
        {children}
      </motion.div>
    );
  }

  // Lit, in place, and nothing to run.
  if (still) return <div className={className}>{children}</div>;

  // The rise is the entrance, on the cell's delay; the brightness is the
  // switch, on the glow's curve. Separate transitions on the one element
  // because they answer to different states.
  const rise = still ? { duration: 0.2 } : { duration: 0.7, ease: EASE, delay };

  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: entered ? 1 : 0, y: entered ? 0 : 10 }}
      transition={{ opacity: rise, y: rise }}
    >
      {children}
      {/* The dim, as black over the card rather than brightness() on it.
                The two are the same arithmetic — brightness(b) scales every
                channel by b, and black at 1-b alpha leaves c*b — but a filter
                re-rasters what it covers on every frame it changes, and what it
                covers here is an export carrying eighteen SVG blur filters. Two
                seconds of that, each way, every time the section passes. As an
                overlay it is one opacity on its own layer, which is the
                compositor's job and nobody else's. Above the copy (z-20), since
                brightness() dimmed that too. */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute inset-0 z-20 bg-black"
        initial={{ opacity: 1 - DIM }}
        animate={{ opacity: lit ? 0 : 1 - DIM }}
        transition={sweep}
      />
    </motion.div>
  );
}
